WITH metrics AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share, LAG(discount_pct, 1) OVER (ORDER BY starts_on ASC, id ASC) AS prev_discount_pct FROM promotions) SELECT promo_code, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END), 0), 2) AS discount_pct_per_welcome5, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'VIP' THEN 1 END), 0), 2) AS discount_pct_per_vip, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list FROM metrics GROUP BY 1 ORDER BY partner_count DESC
